def transform(wb):
    et = wb['Existing Task']
    ad = wb['Additions']
    rt = wb['Retired']
    rows = []
    for r in range(3, 10):
        row = []
        for c in range(1, 6):
            row.append(et.cell(row=r, column=c).value)
        rows.append(row)
    for r in range(3, 7):
        row = []
        for c in range(1, 6):
            row.append(ad.cell(row=r, column=c).value)
        rows.append(row)
    for r in range(3, 5):
        target = []
        for c in range(1, 6):
            target.append(rt.cell(row=r, column=c).value)
        new_rows = []
        removed = False
        for i in range(len(rows)):
            if not removed and rows[i] == target:
                removed = True
            else:
                new_rows.append(rows[i])
        rows = new_rows
    out = wb['Consolidated Tracker']
    for r in range(3, 12):
        for c in range(1, 6):
            out.cell(row=r, column=c).value = None
    for i in range(9):
        if i < len(rows):
            for c in range(5):
                out.cell(row=3 + i, column=1 + c).value = rows[i][c]
